CREATE TABLE IF NOT EXISTS map_guide_backup AS SELECT * FROM idea_references WHERE kind='stage';
CREATE TABLE map_guide_import (title TEXT PRIMARY KEY, image TEXT NOT NULL, brief TEXT NOT NULL);
INSERT INTO map_guide_import VALUES ('深海水族館鬼ごっこ','','【建築に渡す補足・設計案】
敷地：約300×300ブロック。北を上、北西を仮原点X=0/Z=0、東を+X、南を+Zとする。ワールドの地表Yは制作時に読み取り、床面を相対Y=0として計画。
この画像から外観・配置の方向性は決められるが、実測座標・隠れた面・全棟の間取りは確定できない。外観図は構想として維持。建物と道路の接続、地面高、入口方向を記録してから配置する。
代表棟の外形案：90×60。掲載の内装図は機能棟1棟の例で、全施設を同じ部屋にする指定ではない。部屋：大水槽展示室／展示室／売店／管理室／機械室／部品倉庫。
内装候補：大水槽展示室=ガラス水槽／観覧柵、展示室=展示台／解説壁、売店=カウンター／棚、管理室=机／ロッカー、機械室=ポンプ／工具棚、部品倉庫=部品棚／作業台。素材：白色コンクリート・青色ガラス・石系の床。
屋外プールと潜水艇の桟橋を接続。水槽内部と乾いた逃走路を分離する。潜水艇の内部は修理完了まで待機場所にしない。
通路案：屋外主要道8以上、副道5以上、室内主要道8、外周6。扉の有効幅4、有効高さ4を開始案とし、鬼の実当たり判定＋余裕に合わせて調整する。小さい出入口が鬼を制限する設定を勝手に追加しない。室内の天井下4以上、展示・厨房などは8以上を案とする。階段幅4以上、踊り場4×4以上、頭上4以上を案とし、階数と床高を確定して設計する。
6つの対象物の名称・場所・用途は企画本文を優先。探索対象、設置先、装飾を別IDで区別し、最終配置時にX/Y/Z、入口からの経路、運搬の可否を記録する。扉や通路上に家具・装飾を置かない。
未確定：全棟の最終座標と外形、階数、各階の平面、屋根と階段、部品カタログの最新版、鬼の当たり判定、MOD固有ブロック・専用モデル番号。既存ワールドとカタログを読み直して補う。
ファイル上でブロック・座標・個数を検証し、Minecraft内の表示・通行・見通し・マルチ負荷は別に確認。ギミックの実装は人間担当。');
