UPDATE idea_references SET content=json_set(content,'$.brief',(SELECT brief FROM map_guide_import JOIN ideas ON ideas.title=map_guide_import.title WHERE ideas.id=idea_references.idea_id),'$.images[#]',json((SELECT image FROM map_guide_import JOIN ideas ON ideas.title=map_guide_import.title WHERE ideas.id=idea_references.idea_id))) WHERE kind='stage' AND idea_id IN (SELECT id FROM ideas JOIN map_guide_import ON ideas.title=map_guide_import.title) AND json_array_length(content,'$.images')<6 AND instr(content,'【建築に渡す補足・設計案】')=0;
